package com.beouttv.app.data.storage

import android.util.Base64

/**
 * Secure In-Memory Embedded Catalog Vault.
 * Protects channel streams binary payload from being exposed in plaintext inside assets directory.
 * Decodes automatically on first run to the app private sandbox: /data/data/<package_name>/files/libbeout_streams.dat
 */
object EmbeddedStreamsVault {
    const val VAULT_PAYLOAD_HASH = "1ddc4944141bd3135b0feeef360f0b73"
    const val EXPECTED_PAYLOAD_SIZE = 8082

    private val CHUNKS = arrayOf(
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
    )

    fun getPayloadBytes(): ByteArray {
        val sb = StringBuilder(11000)
        for (chunk in CHUNKS) {
            sb.append(chunk)
        }
        return Base64.decode(sb.toString(), Base64.DEFAULT)
    }
}
